from typing import Sequence

def humor(setup: Sequence[float]) -> float:
    """Surprise of a setup: max minus min over its resolutions."""
    return max(setup) - min(setup)

def humor_union_via_extremes(s: Sequence[float], t: Sequence[float]) -> float:
    """Combined surprise from the four extremal resolutions (Combination Law)."""
    return max(max(s), max(t)) - min(min(s), min(t))

def verify_combination_law(s: Sequence[float], t: Sequence[float]) -> bool:
    union = list(set(s) | set(t))
    return abs(humor(union) - humor_union_via_extremes(s, t)) < 1e-12

if __name__ == "__main__":
    cases = [([1,3,4],[2,8]), ([0,0,0],[5]), ([-3,-1],[2,10,4])]
    for s, t in cases:
        print(s, t, "->", humor_union_via_extremes(s, t), "law holds:", verify_combination_law(s, t))

from typing import Optional, Sequence

def humor(setup: Sequence[float]) -> float:
    return max(setup) - min(setup)

def shared_pivot(s: Sequence[float], t: Sequence[float]) -> Optional[float]:
    common = set(s) & set(t)
    return next(iter(common)) if common else None

def additive_defect(s: Sequence[float], t: Sequence[float]) -> float:
    """humor(S union T) - humor(S) - humor(T); <= 0 iff a shared pivot tames it."""
    union = list(set(s) | set(t))
    return humor(union) - humor(s) - humor(t)

if __name__ == "__main__":
    pairs = [([1,5],[5,9]), ([0],[100]), ([0,10],[3,4]), ([0,10],[10,20])]
    for s, t in pairs:
        d = additive_defect(s, t)
        print(f"S={s} T={t} pivot={shared_pivot(s,t)} defect={d} subadditive={d<=1e-12}")

from typing import Sequence

def humor(setup: Sequence[float]) -> float:
    return max(setup) - min(setup)

def is_refinement(s: Sequence[float], t: Sequence[float]) -> bool:
    """True when S refines into T, i.e. every resolution of S lies in T."""
    return set(s) <= set(t)

def functoriality_holds(s: Sequence[float], t: Sequence[float]) -> bool:
    """If S refines T then humor(S) <= humor(T)."""
    if not is_refinement(s, t):
        return True  # vacuous: no arrow S -> T
    return humor(s) <= humor(t) + 1e-12

if __name__ == "__main__":
    chain = [[2,4], [2,4,7], [0,2,4,7], [0,2,4,7,10]]
    for i in range(len(chain)-1):
        s, t = chain[i], chain[i+1]
        print(f"{s} subset {t}: humor {humor(s)} <= {humor(t)} ->", functoriality_holds(s, t))

