from typing import Sequence

def surprise(resolutions: Sequence[float]) -> float:
    """Algorithm A: surprise of a setup in one linear pass.

    Given a finite nonempty configuration of resolutions, return max - min.
    Complexity: O(n) time, O(1) extra space.
    """
    it = iter(resolutions)
    try:
        first = next(it)
    except StopIteration:
        raise ValueError("a setup must be nonempty")
    lo = hi = first
    for x in it:
        if x < lo:
            lo = x
        elif x > hi:
            hi = x
    return hi - lo

